<?php
use DigiForge\Portal\{ProductIntelligencePanel,PrintifySupplierWorkflowPanel};
use DigiForge\POD\{ProductIntelligence,ProductIntelligenceRepository};
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class PrintifyWorkflowPortalTest extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();$_GET=[];}
 protected function tearDown():void{$_GET=[];global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function packet():array{$rows=[['V2 ID'=>'DG2-001','Physical Product'=>'PP-001']];return ['schema_version'=>1,'shop_key'=>'personalized_pod','business_key'=>'digicraftifygoods','catalog_key'=>'digicraftifygoods-master-500-v2','sources'=>[['id'=>'s','name'=>'synthetic.json','sha256'=>str_repeat('a',64),'modified_at'=>'2026-11-06T00:00:00Z']],'sections'=>['concepts'=>['source_id'=>'s','sheet'=>'concepts','rows'=>$rows,'rows_sha256'=>ProductIntelligence::rowsHash($rows)]]];}
 public function testUnauthorizedActorsCannotRenderSupplierSelection():void{wp_set_current_user(0);ob_start();(new PrintifySupplierWorkflowPanel())->render($this->packet(),str_repeat('a',64),home_url('/'));self::assertSame('',ob_get_clean());$id=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($id);ob_start();(new PrintifySupplierWorkflowPanel())->render($this->packet(),str_repeat('a',64),home_url('/'));self::assertSame('',ob_get_clean());}
 public function testOwnerSeesXlsxAndEvidenceWorkflowWithoutExecution():void{PortalAccessFixture::enroll();$saved=(new ProductIntelligenceRepository())->import($this->packet());self::assertNotWPError($saved);$_GET=['df_pi_snapshot'=>$saved['snapshot_id'],'df_shop'=>'personalized_pod','df_pi_blueprint'=>'5','df_pi_provider'=>'7','df_pi_variant'=>'9'];ob_start();(new ProductIntelligencePanel())->render(home_url('/'));$html=ob_get_clean();self::assertStringContainsString('Export section XLSX',$html);self::assertStringContainsString('Supplier-to-product workflow readiness',$html);self::assertStringContainsString('Selected variant has no exact blueprint/provider evidence.',$html);self::assertStringNotContainsString('Generate mockup',$html);}
 public function testForeignShopDoesNotExposeWorkflowOrExportLinks():void{PortalAccessFixture::enroll();$_GET=['df_shop'=>'digital'];ob_start();(new ProductIntelligencePanel())->render(home_url('/'));$html=ob_get_clean();self::assertStringNotContainsString('Export section XLSX',$html);self::assertStringNotContainsString('Review supplier evidence',$html);}
}
